node -e '
const { chromium } = require("<HOME>/git/cronex/demo/node_modules/playwright");
(async () => {
  const browser = await chromium.launch({ headless: true, args: ["--no-sandbox"] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on("pageerror", e => errors.push(String(e)));
  page.on("console", msg => { if (msg.type() === "error") errors.push(msg.text()); });
  await page.goto("file://<WORKSPACE>/index.html");
  await page.waitForTimeout(800);
  const info = await page.evaluate(() => {
    const live = document.documentElement.classList.contains("live");
    const noodles = document.getElementById("noodles").childElementCount;
    const onions = document.getElementById("onions").childElementCount;
    const tilt = document.getElementById("tilt").style.transform;
    const bowl = document.querySelector("svg.bowl").getBoundingClientRect();
    const anims = document.querySelector(".oil").getAnimations().map(a => ({t: a.currentTime, play: a.playState}));
    return { live, noodles, onions, tilt, bowl, anims, w: innerWidth, h: innerHeight };
  });
  console.log(JSON.stringify({ info, errors }, null, 2));
  await page.mouse.move(200, 200);
  await page.waitForTimeout(400);
  const tilt = await page.evaluate(() => document.getElementById("tilt").style.transform);
  console.log("tilt after mouse", tilt);
  await browser.close();
})().catch(e => { console.error("FAIL", e); process.exit(1); });
'

