const { chromium } = require("<HOME>/git/cronex/demo/node_modules/playwright");
(async () => {
  const browser = await chromium.launch({ headless: true, args: ["--no-sandbox"] });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
  const errors = [];
  page.on("pageerror", e => errors.push(String(e)));
  await page.goto("file://<WORKSPACE>/index.html");
  await page.waitForTimeout(700);
  const info = await page.evaluate(() => ({
    text: document.body.innerText.trim(),
    live: document.documentElement.className,
    onions: document.getElementById("onions").childElementCount,
    steam: getComputedStyle(document.querySelector(".steam-static")).opacity,
    anims: document.querySelector(".steam-static").getAnimations().length
  }));
  console.log(JSON.stringify({ info, errors }));
  await page.screenshot({ path: "<TMP>/ramen-mobile.png" });

  const page2 = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  await page2.emulateMedia({ reducedMotion: "reduce" });
  await page2.goto("file://<WORKSPACE>/index.html");
  await page2.waitForTimeout(400);
  const reduced = await page2.evaluate(() => {
    const tilt = document.getElementById("tilt").style.transform;
    const live = document.documentElement.classList.contains("live");
    const canvas = getComputedStyle(document.getElementById("steam")).display;
    const steam = getComputedStyle(document.querySelector(".steam-static")).opacity;
    return { tilt, live, canvas, steam, reduce: matchMedia("(prefers-reduced-motion: reduce)").matches };
  });
  console.log("reduced", JSON.stringify(reduced));
  await page2.mouse.move(100, 100);
  await page2.waitForTimeout(300);
  const tilt2 = await page2.evaluate(() => document.getElementById("tilt").style.transform);
  console.log("tilt after move while reduced", tilt2);
  await page2.screenshot({ path: "<TMP>/ramen-reduced.png" });

  const land = await browser.newPage({ viewport: { width: 844, height: 390 } });
  await land.goto("file://<WORKSPACE>/index.html");
  await land.waitForTimeout(600);
  await land.screenshot({ path: "<TMP>/ramen-land.png" });
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
'

